int tipc_nl_compat_fill_link_msg(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[LINK_ATTR_MAX + 1];
    int err;

    if (!attrs[LINK_ATTR_LINK])
        return -EINVAL;

    link_attr = attrs[LINK_ATTR_LINK];
    err = nla_parse_nested(tb, LINK_ATTR_MAX, link_attr, NULL);
    if (err < 0)
        return err;

    if (!tb[LINK_ATTR_DEST])
        return -EINVAL;

    msg->dest = nla_get_u32(tb[LINK_ATTR_DEST]);

    if (tb[LINK_ATTR_UP])
        msg->status = nla_get_u8(tb[LINK_ATTR_UP]);
    else
        msg->status = 0;

    if (tb[LINK_ATTR_NAME])
        strncpy(msg->name, nla_get_string(tb[LINK_ATTR_NAME]), TIPC_MAX_NAME_SIZE - 1);
    else
        msg->name[0] = '\0';

    return 0;
}

int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[LINKA_MAX + 1];
    int err;

    if (!attrs[LINKA_LINK]) {
        return -EINVAL;
    }

    link_attr = attrs[LINKA_LINK];
    err = nla_parse(tb, LINKA_MAX, nla_data(link_attr), nla_len(link_attr), NULL);
    if (err < 0) {
        return err;
    }

    if (!tb[LINKA_DEST] || !tb[LINKA_STATUS] || !tb[LINKA_NAME]) {
        return -EINVAL;
    }

    msg->dest = nla_get_u32(tb[LINKA_DEST]);
    msg->status = nla_get_u8(tb[LINKA_STATUS]);
    nla_strlcpy(msg->name, tb[LINKA_NAME], sizeof(msg->name));

    return 0;
}

int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *nested;
    int rem;

    if (!attrs[TIPC_NLA_LINK])
        return -EINVAL;

    link_attr = attrs[TIPC_NLA_LINK];
    nla_for_each_nested(nested, link_attr, rem) {
        if (nested->nla_type == TIPC_NLA_LINK_DEST) {
            msg->dest = nla_get_u32(nested);
        } else if (nested->nla_type == TIPC_NLA_LINK_UP) {
            msg->up = nla_get_u8(nested);
        } else if (nested->nla_type == TIPC_NLA_LINK_NAME) {
            strncpy(msg->name, nla_get_string(nested), TIPC_MAX_LINK_NAME);
            msg->name[TIPC_MAX_LINK_NAME] = '\0';
        }
    }

    return 0;
}

int tipc_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NL_LINK_MAX + 1];
    int err;

    if (!attrs[TIPC_NL_LINK])
        return -EINVAL;

    err = nla_parse_nested(tb, TIPC_NL_LINK_MAX, attrs[TIPC_NL_LINK], NULL);
    if (err < 0)
        return err;

    if (!tb[TIPC_NL_LINK_DEST] || !tb[TIPC_NL_LINK_STATUS] ||
        !tb[TIPC_NL_LINK_NAME])
        return -EINVAL;

    nla_put(msg->skb, TIPC_NL_LINK_DEST, strlen(nla_data(tb[TIPC_NL_LINK_DEST])) + 1,
            nla_data(tb[TIPC_NL_LINK_DEST]));
    nla_put(msg->skb, TIPC_NL_LINK_STATUS, sizeof(u32), nla_data(tb[TIPC_NL_LINK_STATUS]));
    nla_put(msg->skb, TIPC_NL_LINK_NAME, strlen(nla_data(tb[TIPC_NL_LINK_NAME])) + 1,
            nla_data(tb[TIPC_NL_LINK_NAME]));

    return 0;
}

int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *link_info;
    int err = -EINVAL;

    if (!attrs[TIPC_NL_COMPAT_ATTR_LINK])
        return -EINVAL;

    link_attr = attrs[TIPC_NL_COMPAT_ATTR_LINK];
    if (!link_attr)
        return -EINVAL;

    link_info = nla_find_nested(link_attr, TIPC_NL_COMPAT_ATTR_LINK_INFO);
    if (!link_info)
        return -EINVAL;

    msg->dest = nla_get_u32(nla_find_nested(link_info, TIPC_NL_COMPAT_ATTR_LINK_DEST));
    msg->status = nla_get_u8(nla_find_nested(link_info, TIPC_NL_COMPAT_ATTR_LINK_STATUS));
    strncpy(msg->name, nla_get_string(nla_find_nested(link_info, TIPC_NL_COMPAT_ATTR_LINK_NAME)), TIPC_NAME_MAX);

    return 0;
}
